insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$lambari$q$, $q$https://www.diariomunicipal.com.br/amm-mg/materia/EBA167B3 (Lei 1.945/2014) ; https://www.diariomunicipal.com.br/amm-mg/materia/53DD3CB7 (Lei 1.943/2014)$q$, $q$Atos oficiais de Lambari: domínio público (Lei 9.610/1998, art. 8º, IV). Geometria das vias: OpenStreetMap (ODbL 1.0, © colaboradores do OpenStreetMap). Limite municipal (registros desativados): IBGE, Malha Municipal (dados públicos).$q$, 10, $q$Lei 1.945/2014: vias que contornam o Parque das Águas (art. 3º) e R. Joaquim Manoel de Melo (art. 4º; também Lei 1.943/2014) proibidas a caminhões em qualquer horário. Trânsito de passagem (art. 1º) e limite de 10 t de carga nas demais vias (art. 7º, p. único) registrados desativados. Carga e descarga (art. 6º) não é restrição de circulação.$q$);
